ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["replies_ask_27"] = {
{"ASK_WHAT_HAPPENED","role=family_man,family_woman,family_youth|tmp=fresh,seasoned|st=friendly,neutral",{"It was the weekend, everyone said it was the flu - then the neighbors started... changing","Friday night, the lights went out, by Sunday nobody was answering the phone"}},
{"ASK_WHAT_HAPPENED","role=family_elder|tmp=seasoned|st=friendly,neutral|world=vehicle",{"I don't know, child, I heard a car alarm and then a scream and then nothing, for a long time"}},
{"ASK_WHAT_HAPPENED","role=family_elder|tmp=seasoned|st=friendly,neutral|world=road",{"I watched my neighbor stagger up the street, he had no business walking, I knew then"}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|tmp=fresh,seasoned|st=friendly,neutral",{"Looked like a bad flu, then folks started biting, I still can't say it out loud","The news said it was contained, then the news stopped"}},
{"ASK_WHAT_HAPPENED","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=trees",{"I was out in the woods, came home to find the town empty - that's all I know"}},
{"ASK_WHAT_HAPPENED","role=civilian_loner|tmp=seasoned|st=friendly,neutral|world=fire",{"Saw smoke from the ridge, saw people running, then it was quiet"}},
{"ASK_WHAT_HAPPENED","role=worker|tmp=seasoned|st=friendly,neutral",{"Whistle blew on Friday, by Monday half the shift didn't come in - those who did, weren't right","Plant manager said go home - we went, we never came back"}},
{"ASK_WHAT_HAPPENED","role=rescue_firefighter|tmp=seasoned|st=friendly,neutral",{"Calls started coming in all at once - bites - fights - fires, we couldn't keep up","The hospital called for us twenty times in an hour - then it stopped calling"}},
{"ASK_WHAT_HAPPENED","role=rescue_medical|tmp=seasoned|st=friendly,neutral",{"It's a pathogen, a bite spreads it - the fever kills, and then the dead walk, that's all I understand","We had a patient who coded and sat up forty minutes later - I haven't slept since"}},
{"ASK_WHAT_HAPPENED","role=rescue_clergy|tmp=seasoned|st=friendly,neutral",{"The Book of Revelation has an answer - I don't, I only know the church bell rang for three days","People came to the church and wouldn't leave, then some of them wouldn't stay dead"}},
{"ASK_WHAT_HAPPENED","role=law_deputy,law_officer|tmp=seasoned|st=friendly,neutral",{"Calls started Friday - Assaults, bites, attacks, by Sunday we'd lost contact with half the county","We were told to keep order, there was no order to keep"}},
{"ASK_WHAT_HAPPENED","role=law_sheriff,law_sergeant|tmp=veteran|st=friendly,neutral",{"I've seen riots and floods, this is neither, it started in the hospitals and spread from there","Federal advisories said quarantine, by then it was already in the courthouse"}},
{"ASK_WHAT_HAPPENED","role=law_trooper|tmp=veteran|st=friendly,neutral|hour=4,9|world=road",{"Highway shut down Friday night, by dawn, the whole interstate was a graveyard"}},
{"ASK_WHAT_HAPPENED","role=law_trooper|tmp=veteran|st=friendly,neutral",{"We were ordered to hold the roadblock, nobody told us what we were holding against"}},
{"ASK_WHAT_HAPPENED","role=law_corrections|tmp=seasoned|st=friendly,neutral",{"Riot in the block on Friday, half the guards didn't come back - the dead did","Inmates stopped answering the count, then they stopped being inmates"}},
{"ASK_WHAT_HAPPENED","role=swat_lead,swat_operator|tmp=veteran|st=friendly,neutral",{"We got called out on a domestic, the suspect wouldn't go down - not with a vest full of rounds","Eight calls in an hour, same thing every time"}},
{"ASK_WHAT_HAPPENED","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral|world=road",{"We got deployed Saturday, nobody told us the target was a street full of people"}},
{"ASK_WHAT_HAPPENED","role=soldier,soldier_green|tmp=seasoned,fresh|st=friendly,neutral",{"We held a checkpoint, then the checkpoint fell - that's all I'm allowed to say"}},
{"ASK_WHAT_HAPPENED","role=soldier_nco|tmp=veteran|st=friendly,neutral",{"Orders came down Saturday - hold the line, the line was the town - we lost it by Monday","Quarantine zone broke in the first 48 hours, I won't speculate on why"}},
{"ASK_WHAT_HAPPENED","role=deserter,militia|tmp=seasoned|st=friendly,neutral",{"They told us to fire on civilians, I put my rifle down and walked","Command collapsed in about two days, everyone for themselves after that"}},
{"ASK_WHAT_HAPPENED","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=friendly,neutral",{"Information is limited, the situation is what it is"}},
{"ASK_WHAT_HAPPENED","role=elite_operator,elite_delta,mercenary|tmp=veteran|st=careful",{"Not discussing it"}},
{"ASK_WHAT_HAPPENED","role=outlaw|tmp=seasoned|st=friendly,neutral",{"Hell if I know, one day the world was normal - next day it was a buffet","Folks got sick, then they got hungry, then they got everyone else"}},
{"ASK_WHAT_HAPPENED","role=raider,raider_boss|tmp=predator|st=friendly,neutral",{"The world ended and I got rich - don't know about you","Everything fell apart, that's an opportunity, if you're quick"}},
{"ASK_WHAT_HAPPENED","role=gang_member,gang_boss|tmp=predator|st=friendly,neutral",{"City went crazy Friday night, by Saturday it was all fire and screaming","Cops ran, then the dead showed up, we held our block"}},
{"ASK_WHAT_HAPPENED","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral|world=road",{"We were coming back from a run, roads were jammed, we left the bikes and ran"}},
{"ASK_WHAT_HAPPENED","role=biker,biker_boss|tmp=predator,veteran|st=friendly,neutral",{"Rode through three towns that were empty, then we found the first ones"}},
{"ASK_WHAT_HAPPENED","role=crime_member|tmp=seasoned|st=friendly,neutral",{"Business slowed Friday, by Saturday nobody was calling - by Sunday nobody was alive","We had warning - not enough - never enough"}},
{"ASK_WHAT_HAPPENED","role=prisoner|tmp=predator|st=friendly,neutral|world=door",{"They locked down the unit, we heard screaming, then the doors opened"}},
{"ASK_WHAT_HAPPENED","role=prisoner|tmp=predator|st=friendly,neutral",{"Guards stopped coming, the dead didn't - we got out the back"}},
{"ASK_WHAT_HAPPENED","reg=law,swat|st=friendly,neutral|day=0,3",{"I don't know, neither do the people in charge, just don't get bitten","They aren't human anymore, the dead walk, shoot them in the head - that's all I've got","Calls came in all night, folks attacking folks, now we're here - fight for your life"}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral",{"I don't KNOW! Friday it's normal, then my neighbor sits up after his heart stopped, and he's- he's HUNGRY","A man bit a woman at the grocery, security tackled him, then she got up, and I ran, that's all I saw, I just ran","Flu, then riot, then the TV just went dead on us...","Everybody got sick, and then everybody got WORSE than sick, and I'm- I'm sorry, I don't want to say the next part","It was a normal day, I was ironing, ironing! and somebody started screaming in the yard","Dead people got up... that's it -- that's what happened, say it out loud and it still sounds insane","N-nobody told us, that's the worst part, nobody told us a single thing before it was too late!!","Ask the Army, ask the government, ask whoever let this out, because it sure as hell wasn't me","I was at work... then my boss was on the floor, then he wasn't, he was on me, I got out through the loading dock","The ambulances came and then they stopped coming, and the sirens didn't, they went on and on and then just..."}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|tmp=fresh|st=friendly,neutral|day=0,3",{"It's only been a few days, can you believe that? a FEW DAYS and everything's gone","Friday I was on the phone with my sister, she said \"hold on, somebody's at the door\" and that was it","They're calling it an outbreak on the radio... an outbreak, like measles, like a bad batch of potato salad!"}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|tmp=seasoned|st=friendly,neutral",{"Short version, someone got bit, someone got sick, someone didn't stay dead, and it took about a week to fall apart","Hospitals filled up, then emptied, then the army shut the roads, and that was that","Nobody knows where it started, and anybody who tells you different is selling something","Started with a rumor, then a body, then it was the whole street","I used to wonder about the end of the world, I never pictured it so quiet, or so smelly...","We got an announcement, \"remain calm,\" then nothing, I think that was the day they gave up on us","A virus... a bug, a bad batch of something, take your pick, the result's the same"}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|st=friendly",{"You really want to know? okay, sit, it's long, but I'll tell you, and I'll try not to cry","I'll tell you what I saw, but don't judge me, I did some things I ain't proud of","I don't know. I keep trying to make sense of it, and I can't"}},
{"ASK_WHAT_HAPPENED","role=civilian_man,civilian_woman|st=careful",{"Why are you asking? who sent you?","Look around, you tell me","That's a long story, and I'm not telling it to a stranger!"}},
{"ASK_WHAT_HAPPENED","role=civilian_loner",{"Sickness, spread by bite, I figured that out in about a day, the rest is just details","I was up the holler hunting when it started, came down to a town full of strangers eating each other","Folks got careless, crowded together, and the thing ran through 'em like a brush fire","Government, military, doesn't matter, somebody opened a door they shouldn't have","I don't speculate, I watch what happens, and what happens is the dead walk","Heard it started at the base, heard it started at the prison, heard it started in Louisville, take your pick","The how doesn't matter, the what-now does, I stick to the second part"}},
{"ASK_WHAT_HAPPENED","role=family_man,family_woman,family_elder,family_youth|st=friendly,neutral",{"We were at my mother-in-law's for Sunday dinner, and she wasn't well, and then she was worse, and then- I can't, please","Like a bad flu at first, then folks started dying, and then they didn't stay dead","My husband went to work Friday morning and the world ended by Friday night","I can tell you what it did to my kids, I can't tell you what caused it","We watched the TV till the TV died, then we watched the street till the street got loud"}},
{"ASK_WHAT_HAPPENED","role=family_elder",{"In my day we'd call it a plague... honey, and the Lord sends them from time to time","I saw it come up the road, people running, the dead behind them, I thought it was the Rapture, and it wasn't","Something in the water, the air, the blood, I read the paper sixty years, and NOBODY warned us"}},
{"ASK_WHAT_HAPPENED","role=family_youth",{"So there's like a virus? or a thing? and when you die you come back? that's literally all I know","My mom said stay home... my dad said stay home, the principal said stay home, and then nobody said anything..","Somebody at my school started biting people in the cafeteria. I don't know why"}},
{"ASK_WHAT_HAPPENED","role=worker",{"Thursday we had a guy come in sick, Friday we had six, Saturday the foreman locked us in the plant for safety","Somebody gave the wrong order somewhere, and a thing got loose, that's how it always goes","Truckers on the CB said it was an accident, a spill, a leak, I don't buy it"}},
{"ASK_WHAT_HAPPENED","role=rescue_medical",{"People came in with fevers and bites, raving, we had nothing to give them, by Saturday nobody was left to work","It looks like a hemorrhagic fever at first, then neurological, then it's something no textbook describes","I wrote it up for the health department... nobody answered, that was Sunday, I stopped writing after that.."}},
{"ASK_WHAT_HAPPENED","role=rescue_clergy",{"It began like a plague from the old Book, and I'm not sure what else to call it","I buried eleven people in two days, and the twelfth got up and walked away, and I haven't buried anyone since","The church bell rang for the first dead, then the second, then we stopped ringing it"}},
{"ASK_WHAT_HAPPENED","role=rescue_firefighter",{"We got a call for a man down, we arrived, he got up and bit my partner, that was our first sign","After that... calls came in so fast we couldn't keep up, ten, twenty, fifty, and then the dispatch went quiet","It was a bad day, and every day after has been worse"}},
{"ASK_WHAT_HAPPENED","role=militia",{"I won't pretend to know, but I saw convoys moving in before anything got bad, and that makes me think","The locals will tell you virus, the military will tell you nothing, I tell you both are lying","The line at the checkpoint didn't hold, and I don't know who to blame"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"You deserve the truth, so here it is, what I saw, what I heard, what I think","Sit down, I'll start at the beginning, and I won't skip the ugly parts!","Because it's you, I'll tell it, I haven't told anyone else","Sit, I'll tell you all of it, from the beginning, since you've earned it","It started with a rumor -- a whisper in the diner, a sick man in the next county","I can tell you what I saw, ain't pretty, and what I heard is worse","I was there for the first night, and I haven't slept right since","The truth is, nobody knows, but I have a theory, and I trust you with it","The ambulance came, then the second, then the third, then none","No one big thing, just a hundred little ones piling up till the whole roof caved","The news said \"isolated incident,\" and I knew right then it was a lie!","My neighbor got sick, and I went to check on her, and she wasn't alone anymore","I'll tell you honestly: I don't understand it, but I'll tell you what I know","One day the radio played static, and the next day it played silence","I won't sugarcoat it, because you wouldn't want me to","The government told us to stay put, and that was the last order anyone gave","It's a long story, with a short, bad ending, but I'll share it with you","They closed the roads, and it spread inside the walls","We were sitting at dinner when the lights flickered, and the dog howled, and then the screaming began","I saw it from the church steps, and I've never been the same","A man stumbled into town, bleeding, and that's all it took!","The sickness came first, but the fear was faster","It started where you'd least expect: a school, a diner, a church picnic","I trust you, so I'll say it plain: somebody lost control of something","There's no explaining it, but there's remembering it, and I remember it all","Let me tell you about the first day, because you deserve to know!","Strange smells, strange sounds, strange silence, and then the first scream, ha","It broke my heart, and then it broke the town","Everything I tell you is true, as far as I know","The doctors didn't know either, I watched them cry","I told my kids it's nobody's fault, and I'm still not sure I believe that","We're survivors, and survivors tell the truth"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=bad,worst",{"I'm NOT telling you anything","Take a look around, I can't explain it"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=careful|rep=bad,worst",{"Don't ask me"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral|mood=fear",{"I saw it- I saw them- he was- no no no, I can't, I can't say it","People fell down... got back up... and then- oh God-","It was loud, it was so LOUD, and then it was so quiet, and the quiet was worse","My mother called me, she was screaming, I couldn't understand her, and the line cut off!","I don't know, I don't know, I don't know, I just ran, I just kept running","I was in the shower","I was driving to work and traffic stopped","I woke up at dawn to a sound like a hundred people moaning"},false,false,{[6]={{t="I heard glass, and a scream, and I just stood there, dripping",afterMs=3500},{t="I put on wet clothes and ran",afterMs=3200}},[7]={{t="people were getting out of their cars -- screaming, running into the fields",afterMs=3500},{t="I locked my doors and prayed",afterMs=3200}},[8]={{t="I opened the curtain",afterMs=3500},{t="and it was my whole street",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|mood=grim",{"Short version, it got loose, and everybody paid the price","Folks got sick, then got worse, then got up, you can fill in the rest","It's the end of the world as we knew it, and there's no radio telling us we're fine","It started slow, then it didn't, and by the time we noticed, it was done","A week ago we had a town, now we have a graveyard with a grocery store","The long version is a week of watching the world forget itself","First the hospitals, then the churches, then the streets, then the silence"},false,false,{[6]={{t="the short version is, it got loose, and nobody was ready",afterMs=3500}},[7]={{t="that's the order it took",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=sad",{"I lost my husband in the first hour... in the first hour... I didn't even say goodbye","The kids' school was the first place... I can't say it... I can't...","My whole street, gone... Dottie, and Frank, and the Millers... all gone","It started on a Friday afternoon, at the ice cream stand","M-my daughter's school called... they said \"keep your child home,\" I laughed","It was my husband who first got sick, a fever, a cough, and by Sunday night he was-"},false,false,{[4]={{t="a man collapsed, and everybody gathered, and then he sat up",afterMs=3500},{t="I can't eat ice cream anymore",afterMs=3200}},[5]={{t="she was at the school, she was already at the school",afterMs=3500}},[6]={{t="I'm sorry, I can't finish",afterMs=3500}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Somebody screwed up, somebody ALWAYS screws up, and we're the ones paying for it","They knew, I know they knew, and they stayed QUIET, and let it spread, the bastards","Don't ask me what happened, ask the ones who made it happen, and send them my regards","I was at the checkpoint, I saw it, they opened fire on a car full of kids","Everyone's saying virus, or chemical, or whatever, I say it's a cover-up"},false,false,{[4]={{t="that's what happened, that's the truth, and nobody will ever say it",afterMs=3500}},[5]={{t="and I'm tired of being QUIET!",afterMs=3500}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly|mood=warm",{"Sit down, I'll tell you, but only if you promise to hold my hand a little while I do","I've been dying to tell someone, and you seem like you'd actually listen","I'll tell you, because I think you ought to know, and because I trust you"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Well, long story short, the dead got up, the living got scared, and I got a flat tire","It's a long story, with a short punchline, everybody died, ha ha ha, I'm kidding, mostly","A man bit another man at a barbecue, and instead of screaming, everyone just- stared","I was at the grocery","The world ended on a Friday... ha","I was in line at the DMV"},false,false,{[3]={{t="Southern manners, you know",afterMs=3200},{t="nobody wanted to be rude",afterMs=3000}},[4]={{t="and a lady in aisle five tried to eat the cashier",afterMs=3000},{t="I'm not kidding, and I still got my coupons validated",afterMs=3200}},[5]={{t="typical",afterMs=3200}},[6]={{t="best day of my life, until the line started biting",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=careful|mood=fear",{"I'm not telling you... ask someone else","Why? so you can use it against me?"}},
{"ASK_WHAT_HAPPENED","role=rescue_medical|st=friendly,neutral",{"Fever first, then confusion, then a stillness I've never seen, and then... then they sat up","I've been a nurse twenty years... and I've never seen a heart stop and start again, never, until Friday..","The ER filled in an hour, by midnight we had no beds, by morning we had no staff","We tried everything: IVs, oxygen, restraints, prayers, nothing held","My supervisor said, \"do not let anyone leave,\" and then she left, I don't blame her","Doctors argued over what to call it, and meanwhile, the call lights kept going off"}},
{"ASK_WHAT_HAPPENED","role=rescue_medical|st=careful",{"I'm not discussing what I saw, it's confidential, and it's horrifying"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=calm",{"It began, as far as I can tell, with a rumor about a bad flu","I kept a diary the first three days, then the pen ran out"},false,false,{[1]={{t="then people stopped coming to church, and the rumor grew legs",afterMs=3500}},[2]={{t="you don't want to read it",afterMs=3500}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=careful",{"I'm not discussing it","If you don't know, you haven't been paying attention","You know what happened","I'm not going over it again, not for you","It happened to all of us","Ask somebody who wasn't there","Look around","I won't relive it for you","What happened is you walked up on me too fast - back up a few steps and ask me again","You don't know? Where've you been that you don't know? Keep your hands where I can see 'em"},false,false,{[3]={{t="everyone does",afterMs=3000}},[5]={{t="that's all",afterMs=3000}},[7]={{t="there's your answer",afterMs=3000}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best|hour=16,5",{"First the fevers, then the quiet, then the knocking... that's all I'll say tonight"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"Ask someone who cares to tell you","What happened? You happened, near enough","I won't tell you a thing","I'm not in the mood to chat with you","You want a story? Go look in a mirror!","It's not for you to know","If you were paying attention, you wouldn't ask","I told the last person who asked, and look what happened","You're the last person I'd tell","Read the writing on the wall","I'll tell it to someone worthy","The story isn't for sale!","Not today","I'd rather not relive it for you","You don't deserve my breath!","I'd sooner tell it to the wind!","It happened, and then you came along","Why do you want to know? what's it to you?","Look around, you'll figure it out","I'm not a historian, and you're not an audience","It's a long story, and you're not in it","That's none of your business","Ask the DEAD!!","Find a book, or a priest, or a fool","You wouldn't understand, or you'd twist it","Keep your questions, and your nose, out of it","I can't talk about it with you","No comment","We don't discuss that around here, especially with you","Gossip is for friends","There's no story for you","I'll spare you the details, and myself the trouble"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"That! THAT is what happened, right there!","Later, later, tell you later, right now we run","I- it's happening again, right now, right here","No time to explain, no time, move","They happened -- they're happening, they're about to happen to us","I'd love to tell you... but we have company!","Stories after survival, survival first","It's still happening, it never stopped, look!"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"Something bad, something that needs people like you, armed and ready"}},
{"ASK_WHAT_HAPPENED","role=civilian_loner|st=friendly,neutral",{"I came out of the woods and the world had changed","First I smelled it","A man stumbled up my trail -- begging..","Something got loose","The animals knew"},false,false,{[1]={{t="the dogs knew first",afterMs=3500},{t="I should have listened",afterMs=3000}},[2]={{t="on the wind, from the valley",afterMs=3200},{t="that sweet rot",afterMs=2800}},[3]={{t="I gave him water",afterMs=3500},{t="he took it, and then he took a bite",afterMs=3000}},[4]={{t="and the folks in town were too crowded to run",afterMs=3200}},[5]={{t="deer came down from the ridge, and the crows left town",afterMs=3500}}}},
{"ASK_WHAT_HAPPENED","role=civilian_loner|st=careful",{"You ask too many questions"}},
{"ASK_WHAT_HAPPENED","role=family_elder|st=friendly,neutral",{"I was shelling beans on the porch when the sirens started","The sickness came on the wind, I think","It began with the cough","Dear, I lived through the polio summers"},false,false,{[1]={{t="I thought it was the Fourth of July",afterMs=3500},{t="it was something else",afterMs=3000}},[2]={{t="that's what Doc Harrison said, before he went",afterMs=3200}},[3]={{t="a cough in the church",afterMs=3500},{t="then a cough in every pew",afterMs=3000}},[4]={{t="and the Korean war",afterMs=3200},{t="I've never seen anything like this",afterMs=2800}}}},
{"ASK_WHAT_HAPPENED","role=family_elder|st=careful",{"Ask the young ones, they have a screen for EVERYTHING!"}},
{"ASK_WHAT_HAPPENED","role=family_youth|st=friendly,neutral",{"Somebody got sick, like REALLY sick, then died, then... un-died","I was at a friend's house, we were watching TV","Mom said it was nothing","Everything went weird on Friday"},false,false,{[1]={{t="it's so messed up",afterMs=3500}},[2]={{t="and the news just stopped",afterMs=3200},{t="like, the anchor stood up and walked off camera",afterMs=3000}},[3]={{t="Dad said it was something",afterMs=3500},{t="now they're both quiet",afterMs=3000}},[4]={{t="the phones, the TV, the lights",afterMs=3200},{t="and then the screaming",afterMs=2800}}}},
{"ASK_WHAT_HAPPENED","role=family_youth|st=careful",{"Who wants to know?"}},
{"ASK_WHAT_HAPPENED","role=worker|st=friendly,neutral",{"Friday, shift change, a guy collapsed on the line","Nobody told us anything -- we just got an announcement to go home","The guy next to me at the machine... he coughed blood on the part","It was fast"},false,false,{[1]={{t="we thought it was heat",afterMs=3500},{t="then he got up",afterMs=3000}},[2]={{t="half of us never made it",afterMs=3200}},[3]={{t="I stopped the line",afterMs=3500},{t="that's the last thing I did as a foreman",afterMs=3000}},[4]={{t="one week",afterMs=3200},{t="that's all it took",afterMs=2800}}}},
{"ASK_WHAT_HAPPENED","role=worker|st=careful",{"Ask management"}},
{"ASK_WHAT_HAPPENED","role=family_man,family_woman|st=friendly,neutral",{"We were at my in-laws' for dinner when the news broke","The kids' school called... said to pick them up..","My wife was at the store"},false,false,{[1]={{t="my father-in-law stood up and went to the window",afterMs=3500},{t="he never sat back down",afterMs=3000}},[2]={{t="I ran",afterMs=3200},{t="I don't remember the drive",afterMs=2800}},[3]={{t="she came home with her arm wrapped in a shirt",afterMs=3500},{t="and a look I'll never forget",afterMs=3000}}}},
{"ASK_WHAT_HAPPENED","role=family_man,family_woman|st=careful",{"That's not for strangers"}},
{"ASK_WHAT_HAPPENED","role=rescue_clergy|st=friendly,neutral",{"I was in the vestry, preparing for Sunday","It came upon us like the plagues of old","The first funeral was a Saturday...","I cannot explain it"},false,false,{[1]={{t="a man stumbled in, calling for water",afterMs=3500},{t="he died at the altar",afterMs=3000}},[2]={{t="and the Book said nothing about it",afterMs=3200}},[3]={{t="by Tuesday I'd stopped counting",afterMs=3500}},[4]={{t="I can only tell you what I saw: love, and fear, and then the quiet",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","role=rescue_clergy|st=careful",{"I won't speak of it with a stranger"}},
{"ASK_WHAT_HAPPENED","role=rescue_firefighter|st=friendly,neutral",{"We got a call for a man down at the grocery...","Dispatch started sending us to the same address over and over","We pulled twelve out of a church basement","The calls didn't stop"},false,false,{[1]={{t="we arrived",afterMs=3500},{t="he sat up",afterMs=3000}},[2]={{t="nobody there but the dead",afterMs=3200}},[3]={{t="only four were breathing",afterMs=3500}},[4]={{t="they just got worse",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","role=rescue_firefighter|st=careful",{"Ask the survivors!"}},
{"ASK_WHAT_HAPPENED","role=militia|st=friendly,neutral",{"We got called out on a Friday","Orders changed three times in the first hour","The first night, we lost four to friendly fire"},false,false,{[1]={{t="thought it was a drill",afterMs=3500},{t="it wasn't a drill",afterMs=3000}},[2]={{t="then they stopped",afterMs=3200}},[3]={{t="fog of war, they call it",afterMs=3500},{t="it was fog of fear",afterMs=3000}}}},
{"ASK_WHAT_HAPPENED","role=militia|st=careful",{"That's classified"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,3",{"It was Friday, Friday afternoon, everything normal, and then","I can't make sense of it, it happened THIS WEEK, it's still happening","It started on the Fourth... I think, or just after...","Three days ago I had a job, a house, a husband"},false,false,{[3]={{t="nobody knows",afterMs=3500}},[4]={{t="two of those are gone",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|day=4,14",{"About a week ago, everything fell apart","Last Friday","The first few days were chaos, now it's just survival"},false,false,{[1]={{t="it took less than a day for the town to go quiet",afterMs=3500}},[2]={{t="I'll never forget the sound",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral|day=15,99999",{"Weeks ago, now","It was the start of the summer -- and now the summer's nearly gone..","The details blur, but the feeling never does","I don't tell it anymore"},false,false,{[1]={{t="it feels like another life",afterMs=3500},{t="like a movie I saw once",afterMs=3000}},[4]={{t="it's been so long, and so long ago, and so close",afterMs=3200}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly,neutral",{"I was washing dishes..","My husband was fixing the mower when the neighbors started screaming","It was a Friday afternoon","I was at church","I worked the night shift","My brother called and said turn on the TV","I drove through three towns that morning","It started in the next county","A man walked into my store, white as a sheet, and asked for a glass of water"},false,false,{[1]={{t="through the window I saw a man walking across the yard with his arms out",afterMs=3500},{t="he walked right into the fence, and kept walking, into the fence",afterMs=3000}},[2]={{t="he went to see, I stayed with the baby...",afterMs=3500},{t="that's the last I saw of him",afterMs=3000}},[3]={{t="I was late picking up my boy",afterMs=3200},{t="I found his school empty, the doors open, the lunchboxes on the tables",afterMs=2800}},[4]={{t="the choir was mid-hymn",afterMs=3500},{t="somebody in the back pew started coughing, and didn't stop",afterMs=3000}},[5]={{t="the patient in bed six flatlined... I called a code",afterMs=3200},{t="he sat up, before we even started",afterMs=2800}},[6]={{t="every channel had the same man saying the same thing",afterMs=3500},{t="\"do not approach\"",afterMs=3000}},[7]={{t="every town had its sirens going",afterMs=3200},{t="by evening, no sirens",afterMs=2800}},[8]={{t="we thought it was a long way off",afterMs=3500},{t="it was one day off",afterMs=3000}},[9]={{t="he drank it",afterMs=3500},{t="and asked for another, and another, then he stopped breathing",afterMs=3000}}}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=friendly",{"Sit with me, I'll tell you, but hold my hand through the bad part"}},
{"ASK_WHAT_HAPPENED","reg=raider|st=neutral,careful",{"The whole damn world fell on its face and I got a front row seat with a gun in my hand, best thing that ever happened","You really don't know? Friday night people started biting people, what rock were you hiding under?","Dead folks got up and went for the living, and nobody with a badge showed to fix it, that's what happened","I was in the middle of a job, looked up, whole street was screaming -- and I thought, huh, there goes the neighborhood","Rules ended, simple as that, now it's whoever's got the most guns and the least manners","Something knocked out everybody who used to tell me what to do, so no, I'm not crying about it","My boss turned on me in the middle of a count, bit a chunk out of a guy's neck... best day of my life, honestly","It all went to hell in about six hours, then the radio died, then the lights flickered, then it was us","You want the long version or the one where I don't get bored? Dead walk, the living lose, I don't","Don't act like you didn't see it, half the county's chewing on the other half"}},
{"ASK_WHAT_HAPPENED","reg=raider|st=hostile",{"You want a history lesson? Take one from the dirt!","Happened is, you stumbled up on the wrong guy at the wrong time -- keep talking, find out more","Ask the dead, they're real chatty right before they eat you"}},
{"ASK_WHAT_HAPPENED","reg=raider|st=friendly",{"Honestly? I dunno, {g:man|lady}... one minute I am having a beer, next my neighbor is chewing his wife's arm, can't unsee it","Friday the ninth, I'll never forget it, sirens never stopped and then they did all at once","I wish I could tell you, I keep going over it and over it, none of it makes sense","Just a regular night, then screaming, then it never stopped... I don't wanna talk about it, sorry"}},
{"ASK_WHAT_HAPPENED","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"The old world died and somebody had to pick up the pieces, I intend to be the somebody","What happened is a lot of weak people stopped being a problem"}},
{"ASK_WHAT_HAPPENED","reg=gang|st=neutral,careful",{"Everything went crazy, my cousin got bit at the cookout then he ate my aunt, I'm not making this up","Whole block lost its mind, cops stopped coming, it was every man for himself","Folks started turning, the news went dark, and now WE are the law, you feel me?","Nobody knows, but I'll tell you this -- it ain't stopping","We were having a regular Friday, then somebody started screaming at the corner store and it spread like wildfire","Mama called me crying about the neighbors, by the time I got there she was gone, that's what happened","Dead people eating live people, how many ways you want me to say it?"}},
{"ASK_WHAT_HAPPENED","reg=gang|st=hostile",{"Ask the dead, they'll tell you, right before they eat your face","What happened is you walked into the wrong block, that's what!"}},
{"ASK_WHAT_HAPPENED","reg=gang|st=friendly",{"Man... I wish I knew, I lost half my people in the first two days, still can't believe it","One day we're running the streets, next day the streets are running us, hand to God"}},
{"ASK_WHAT_HAPPENED","reg=club|st=neutral,careful",{"We were at a rally, hand to God, whole crowd just turned, brothers eating brothers","Who the hell knows, I was on the road and by the time I got back it was already over","The Army locked the county and left us to rot, that's what happened","Somebody screwed up somewhere and we're paying for it, always the same","I was on the highway when the radio started going nuts, by the time I stopped, everything was burning","Folks got sick, got mean, got dead, got up again, in that order"}},
{"ASK_WHAT_HAPPENED","reg=club|st=hostile",{"What happened is you asked the wrong man the wrong question"}},
{"ASK_WHAT_HAPPENED","reg=club|st=friendly",{"{g:Brother|Sister}, I don't know either, but I know we gotta stick together now","Lost four of my guys in a day, I'm still trying to wrap my head around it"}},
{"ASK_WHAT_HAPPENED","reg=crime|st=neutral,careful",{"There was an incident, then a cover-up, and now there's this, fill in the rest yourself","Someone made a mistake, and everyone is paying for it, as usual","Rumor is it started at a plant and spread, but rumors are cheap","My sources said the Army knew and let it go anyway, which doesn't surprise me","It looked like a flu, then like a riot, then like the end of everything"}},
{"ASK_WHAT_HAPPENED","reg=crime|st=friendly",{"I lost three associates in one night, it's hard to put into words"}},
{"ASK_WHAT_HAPPENED","reg=prison|st=neutral,careful",{"We were on lockdown, then the guards started screaming, then the lights went out... that's how I got out","The whole place went crazy, dead men walking in the cafeteria, I-- I saw things I can't say","I don't know, honest, I was in a cell, I only heard the screaming through the vents","Guards ran, doors opened, so I ran... that's it, that's ALL I know","Nobody told us anything, one day the hacks just stopped coming, and then the sounds started"}},
{"ASK_WHAT_HAPPENED","reg=prison|st=hostile",{"I don't know! Don't ask me! Leave me alone!","Somebody died, somebody got up, I got out, end of story!"}},
{"ASK_WHAT_HAPPENED","reg=prison|st=friendly",{"Honestly? Best day of my life and the worst, hard to explain"}},
{"ASK_WHAT_HAPPENED","reg=outlaw|st=neutral,careful",{"Folks got sick, died, got up, bit their families -- pretty straightforward when you boil it down","Sheriff's office went quiet first, then the radios, then everything else","I was camping up in the hills, came down and the whole town was on fire","One day the grocery store was full of people, next day it was full of something else","Somebody dropped the ball and the ball broke the county"}},
{"ASK_WHAT_HAPPENED","reg=outlaw|st=hostile",{"You want answers, ask the dead"}},
{"ASK_WHAT_HAPPENED","reg=outlaw|st=friendly",{"Nobody knows, friend, but I'm glad we both made it this far"}},
{"ASK_WHAT_HAPPENED","role=deserter|st=neutral,careful",{"I-- they told us to hold the line, then they told us to run, I don't know what happened in between","We got orders to fire on civilians, I didn't do it, cross my heart I didn't"}},
{"ASK_WHAT_HAPPENED","reg=law|st=neutral,careful",{"Calls came in all night, the dispatchers couldn't keep up, then the lines went dead","First it looked like a riot, then a disease, now I don't know what to call it","Nobody told us a thing, we found out when the first deputy got bitten","We got reports of assaults, then more, then they stopped being assaults and started being something worse","It started at the hospital, a man died and stood back up, and I knew right then","It went from bad to worse so fast, I'm still trying to remember what day it is"}},
{"ASK_WHAT_HAPPENED","reg=law|st=hostile",{"That's not a question you should be asking, answer mine instead"}},
{"ASK_WHAT_HAPPENED","reg=law|st=friendly",{"It's a nightmare, but we'll get through it together, I promise you that","Honestly, I don't have good answers either, but I'm glad to see someone alive"}},
{"ASK_WHAT_HAPPENED","role=law_sheriff|st=neutral,careful",{"It started as a flu on the north end of the county, within two days we had bodies in the street"}},
{"ASK_WHAT_HAPPENED","role=law_trooper|st=neutral,careful",{"Highways jammed, people trying to leave, then the roadblocks went up and nobody could"}},
{"ASK_WHAT_HAPPENED","role=law_sergeant|st=neutral,careful",{"I saw it first at the hospital, a man died and stood back up, and I knew"}},
{"ASK_WHAT_HAPPENED","role=law_corrections|st=neutral,careful",{"Inmate bit a guard, guard bit a guard, within an hour the cell block was a slaughterhouse"}},
{"ASK_WHAT_HAPPENED","reg=swat|st=neutral,careful",{"We got called for a barricade, that barricade turned out to be the first of many","Entered a house on a domestic, found something that was not a domestic"}},
{"ASK_WHAT_HAPPENED","reg=military|st=neutral,careful",{"We were deployed under quarantine protocol, that's all I can tell you","Orders came to seal the county, we sealed it, that's what happened","Outbreak, and it's beyond containment, that's the official word"}},
{"ASK_WHAT_HAPPENED","reg=military|st=hostile",{"That information is classified, civilian"}},
{"ASK_WHAT_HAPPENED","reg=military|st=friendly",{"Honestly, I don't know much more than you, it's a mess for everybody"}},
{"ASK_WHAT_HAPPENED","role=soldier_nco|st=neutral,careful",{"Got the call at 0300, by 0500 we knew we were in over our heads"}},
{"ASK_WHAT_HAPPENED","role=soldier_green|st=neutral,careful",{"They sent us in and nobody told us what we were walking into, I'm sorry, I'm so sorry","Everybody's dead or turned and I'm just a kid in a uniform, I don't understand any of it"}},
{"ASK_WHAT_HAPPENED","reg=elite|st=neutral,careful",{"Containment failure, beyond that I won't say"}},
{"ASK_WHAT_HAPPENED","role=mercenary|st=neutral,careful",{"Whatever it was, somebody paid big to keep it hush"}},
{"ASK_WHAT_HAPPENED","role=militia|st=neutral,careful",{"Neighbors started dying, then getting back up, we barricaded the farm, that's how it was","Folks in town got sick first, we heard the screaming from the ridge, nobody came to help","We watched it on the six o'clock news until they stopped broadcasting, then we watched the smoke"}},
{"ASK_WHAT_HAPPENED","role=militia|st=hostile",{"What happened is we got abandoned, and we won't be again"}},
{"ASK_WHAT_HAPPENED","role=militia|st=friendly",{"God knows, friend, but we're doing what we can to get through"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"I don't know! Mr. Tate was mowing his lawn Friday, and by supper he was biting the mailman - that's what happened","People got sick, and then they got up again, that's all I know, and honestly I wish I didn't know that much","The TV went to that beeping emergency screen and then just snow - we thought a storm knocked the cable out, we really thought that"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family|tmp=fresh|st=friendly|day=0,4",{"Radio says it's a sickness that makes folks violent - Army should have it handled by the weekend - you headed out too? Walk with me a bit?"},false,{[1]="WALK_TOGETHER"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=building,road",{"You're asking me like I'd know, I was asleep on the couch with the fan on - woke up and the whole street was screaming"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"Folks started biting folks, then the bitten ones did the same - rest is just arithmetic","The county died over about a week, phones first, then the power, then the neighbors"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|day=8,9999",{"Same thing that happened everywhere around here, you're standing in what's left of it"}},
{"ASK_WHAT_HAPPENED","reg=civilian,family,worker,rescue|st=hostile",{"The world went to hell and now you're in my face asking about it - move along"}},
{"ASK_WHAT_HAPPENED","reg=worker|st=friendly,neutral|world=door",{"I was on second shift at the warehouse in Muldraugh when the foreman said lock the bay doors - we locked 'em - didn't help"}},
{"ASK_WHAT_HAPPENED","reg=worker|st=friendly,neutral",{"Plant sent everybody home early Friday, said there was a chemical thing - nobody told us it could walk"}},
{"ASK_WHAT_HAPPENED","reg=rescue|role=rescue_firefighter,rescue_medical|st=friendly,neutral",{"We ran more calls that Friday night than all of June - every one of 'em was a bite, by Sunday dispatch stopped picking up"}},
{"ASK_WHAT_HAPPENED","reg=rescue|role=rescue_medical|st=friendly,neutral",{"It's an infection, the bite gives you a fever, the fever takes you, and then you get up - I watched it happen on my own stretcher"}},
{"ASK_WHAT_HAPPENED","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"The Lord's people are being tested, I don't pretend to know more than that, and anybody who says they do is selling something"}},
{"ASK_WHAT_HAPPENED","reg=law,swat|st=friendly,neutral|world=road",{"Calls stacked up Friday - Assaults, all of 'em bites, by Saturday we had more units down than on the road"}},
{"ASK_WHAT_HAPPENED","reg=law,swat|st=friendly,neutral",{"{sir}, it was a mass casualty event that got away from everybody, all the way up"}},
{"ASK_WHAT_HAPPENED","reg=law|st=friendly,neutral",{"Dispatch went quiet the third night, last traffic I heard was a deputy asking for anybody - anybody at all"}},
{"ASK_WHAT_HAPPENED","reg=law,swat|st=careful,hostile",{"That's not your concern right now - keep your hands out of your pockets and keep walking","I'm not doing a press conference out here - step back, and I mean now"}},
{"ASK_WHAT_HAPPENED","reg=military,elite|st=friendly,neutral",{"Outbreak, county's under quarantine, that's all I was told"}},
{"ASK_WHAT_HAPPENED","reg=military|st=friendly,neutral",{"We were brought in to hold a line, then the line started coming at us from the inside"}},
{"ASK_WHAT_HAPPENED","reg=elite|st=friendly,neutral,careful",{"Containment failed, that's the short version, and it's the only one you're getting"}},
{"ASK_WHAT_HAPPENED","reg=military,elite|st=careful,hostile",{"Negative - keep your distance and state your business"}},
{"ASK_WHAT_HAPPENED","reg=military|st=careful,hostile",{"You're inside a quarantine perimeter walking up on an armed soldier - that's what's happening right now"}},
{"ASK_WHAT_HAPPENED","reg=outlaw,raider,crime|st=friendly,neutral",{"What happened? Nobody's collecting rent anymore, that's what, best month of my life, apart from the biting"}},
{"ASK_WHAT_HAPPENED","reg=prison|st=friendly,neutral",{"Guards ran off Saturday and left the blocks open, some of us got out - some of the guards didn't"}},
{"ASK_WHAT_HAPPENED","reg=gang|st=friendly,neutral",{"Whole city's eating itself, {g:man|lady}, we rolled out of Louisville while it was still on fire"}},
{"ASK_WHAT_HAPPENED","reg=club|st=friendly,neutral",{"We were at a rally down by Brandenburg when the county went crazy - ain't been home since, home ain't there"}},
{"ASK_WHAT_HAPPENED","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"What happened is you got lost and walked up on the wrong people"}},
{"ASK_WHAT_HAPPENED","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Keep asking questions and you'll find out firsthand"}},
{"ASK_WHAT_HAPPENED","reg=raider,prison,gang|st=careful,hostile",{"The end of your luck, {g:pal|lady}, that's what happened - now keep walking before it gets worse"}},
{"ASK_WHAT_HAPPENED","reg=civilian|tmp=fresh|st=friendly,neutral",{"Friday, it started Friday, and by Sunday nobody was answering a phone"}},
{"ASK_WHAT_HAPPENED","reg=family|st=neutral|mood=grim|world=road",{"It came up the road house by house, that's what happened - house by house"}},
{"ASK_WHAT_HAPPENED","reg=worker|tmp=seasoned|st=neutral|world=building",{"One day it was news about a city somewhere, two days later it was the driveway"}},
{"ASK_WHAT_HAPPENED","role=rescue_medical|st=neutral",{"Emergency room filled up Friday night and never emptied, that's what happened"}},
{"ASK_WHAT_HAPPENED","role=law_sheriff|st=neutral|mood=grim",{"I took a call about a man biting his wife on the ninth - I think on that every day"}},
{"ASK_WHAT_HAPPENED","role=soldier_nco|tmp=veteran|st=neutral",{"Sent in to assist civil authority, and there ain't any civil authority left to assist"}},
{"ASK_WHAT_HAPPENED","role=rescue_clergy|st=neutral",{"I don't know what happened, I know what I did after, and I'd rather talk about that"}},
{"ASK_WHAT_HAPPENED","reg=civilian|tmp=seasoned|st=neutral|mood=sad",{"The fourth was normal, that's what I keep coming back to, the fourth was normal"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"I heard it too, I heard it, oh God, what was that? shh, shh, quiet, listen","That noise, that WAS a noise, it wasn't just me, right? please say it wasn't just me","Don't move... don't breathe -- don't make a sound, wait for it to pass","It sounded like something dragging -- or scratching, or moaning, I can't tell, it's everywhere!","I don't know, I don't want to know, let's go the other way, quietly, now"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Could be anything, a branch, a raccoon, a dead one, wait and listen","Not one of ours, I know all our sounds, this is new","Freeze... get low, weapon up, and don't go poking at it","That's a bad noise, a noise that wants something"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|world=wind",{"Give it a minute, if it repeats, it's a person, if it doesn't, it was the wind"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|st=friendly",{"Stay with me, we'll look together, or better, we'll leave together"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|st=careful",{"Why are you asking me? you made it","You did that, didn't you?","You made that noise, didn't you?!","What was that? Did you bring somebody with you?","Don't move, if that's your friends, you tell them to stay put - right now"},false,{[4]="GENERIC"}},
{"ASK_WHAT_IS_THAT","role=civilian_loner",{"Deer, maybe, or a fox, or a man, I'll know in a second, quiet"}},
{"ASK_WHAT_IS_THAT","role=militia",{"I don't know. Give me a second to listen"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"SHH! shh, shh, did you hear that?! DID YOU HEAR THAT?!","That was close- that was too close- listen- LISTEN","Oh God, it's coming this way, it's coming this WAY","I don't know, I don't know... just don't move","What was that?! what the hell was that?!"}},
{"ASK_WHAT_IS_THAT","reg=civilian,family,worker,rescue|st=friendly,neutral",{"That? ...I don't know","Hear it? Hear it? There it is again","What the hell was THAT? Did you do that?","I heard it, I heard it, I'm trying not to throw up"},false,false,{[1]={{t="stay still",afterMs=2500},{t="stay still",afterMs=2500}}}},
{"ASK_WHAT_IS_THAT","reg=raider|st=neutral,careful",{"That? I heard it too... stay quiet, don't move","Probably nothing, probably, but keep your hand on your weapon","Shh, listen, there it is again, did you hear that?","What was what? I didn't hear anything, are you hearing things?","Could be one of them, could be a person, either way, get ready"}},
{"ASK_WHAT_IS_THAT","reg=raider|st=hostile",{"Quiet! Shut your mouth! Something's out there!"}},
{"ASK_WHAT_IS_THAT","reg=raider|st=friendly",{"I don't know... I really don't know, and that scares me worse than anything","Oh God, I heard it- what do we do?!"}},
{"ASK_WHAT_IS_THAT","reg=gang|st=neutral,careful",{"Hold up, I heard it too, stay low","Could be nothing, could be trouble, let's not find out","Be quiet, I'm listening"}},
{"ASK_WHAT_IS_THAT","reg=gang|st=hostile",{"Shhh! Shut up! I can't hear!"}},
{"ASK_WHAT_IS_THAT","reg=gang|st=friendly",{"Man, I'm freaked out, I heard it too, stay close to me"}},
{"ASK_WHAT_IS_THAT","reg=club|st=neutral,careful",{"Sounds like trouble, {g:brother|sister}, grab your piece","Don't move, let it come to us"}},
{"ASK_WHAT_IS_THAT","reg=club|st=hostile",{"Get down! Down, now!"}},
{"ASK_WHAT_IS_THAT","reg=club|st=friendly",{"I heard something, too, I'm not afraid, I'm... cautious"}},
{"ASK_WHAT_IS_THAT","reg=crime|st=neutral,careful",{"I heard it, too, an unwelcome interruption","Let us remain calm and still, it may pass"}},
{"ASK_WHAT_IS_THAT","reg=crime|st=friendly",{"I suggest we withdraw quietly, just in case"}},
{"ASK_WHAT_IS_THAT","reg=prison|st=neutral,careful",{"Oh God... I heard that, what IS that?","Shhh! Freeze!"}},
{"ASK_WHAT_IS_THAT","reg=prison|st=hostile",{"Shut up! Shut up! It's coming!"}},
{"ASK_WHAT_IS_THAT","reg=prison|st=friendly",{"Hold my hand, please, I'm so scared"}},
{"ASK_WHAT_IS_THAT","reg=outlaw|st=neutral,careful",{"Could be a deer, could be a dead one, wait for it","Listen, don't speak, you'll hear it again"}},
{"ASK_WHAT_IS_THAT","reg=outlaw|st=friendly",{"I heard it too, stay close, we'll check it out together"}},
{"ASK_WHAT_IS_THAT","reg=law|st=neutral,careful",{"Hold your position, I'll investigate","Stay behind me, I'll check it out","Could be a patrol, could be hostile, remain alert"}},
{"ASK_WHAT_IS_THAT","reg=law|st=hostile",{"Get down! Stay behind cover!"}},
{"ASK_WHAT_IS_THAT","reg=law|st=friendly",{"I heard it too, stay calm, we'll handle it"}},
{"ASK_WHAT_IS_THAT","reg=military|st=neutral,careful",{"Maybe something. Keep quiet a second and listen","Hold position, scan your sector"}},
{"ASK_WHAT_IS_THAT","reg=military|st=friendly",{"Stay behind me, friend, I've got you"}},
{"ASK_WHAT_IS_THAT","role=soldier_green|st=neutral,careful",{"I heard it, I HEARD it, it's behind us, right? It's behind us!"}},
{"ASK_WHAT_IS_THAT","role=militia|st=neutral,careful",{"Hang back, I'll look, I know every sound on this land"}},
{"ASK_WHAT_IS_THAT","role=militia|st=friendly",{"Old well pump, probably... I'm not sure, stay close"}},
